/* ==UserStyle==
@name npmx Catppuccin
@namespace github.com/catppuccin/userstyles/styles/npmx
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/npmx
@version 2026.11.14
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/npmx/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Anpmx
@description Soothing pastel theme for npmx
@author Catppuccin
@license MIT

@preprocessor less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("npmx.dev") {
  :root[data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }
  :root[data-theme="light"] {
    #catppuccin(@lightFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --bg: @base;
    --bg-subtle: @mantle;
    --bg-muted: @crust;
    --bg-elevated: @surface0;

    --fg: @text;
    --fg-subtle: @overlay1;
    --fg-muted: @subtext0;
    --fg-elevated: @subtext0;

    --accent: @accent;
    --accent-muted: @accent;

    --border: @surface1;
    --border-subtle: @surface0;
    --border-hover: @overlay0;

    --swatch-sky: @sky;
    --swatch-coral: @peach;
    --swatch-amber: @yellow;
    --swatch-emerald: @green;
    --swatch-violet: @mauve;
    --swatch-magenta: @pink;
    --swatch-neutral: @text;

    --badge-orange: @peach;
    --badge-yellow: @yellow;
    --badge-green: @green;
    --badge-cyan: @teal;
    --badge-blue: @blue;
    --badge-indigo: @lavender;
    --badge-purple: @mauve;
    --badge-pink: @pink;

    --colors-red-500: @red;
    --colors-emerald-500: @green;
    --colors-yellow-600: @yellow;
    --colors-amber-500: @peach;
    --colors-emerald-400: @green;
    --colors-orange-500: @peach;
  }
}

